<template>
  <view class="stack-page"><view class="stack-shell" @mousemove="onShellMouseMove" @mouseup="onShellMouseEnd">
    <view class="stack-header"><view class="brand"><view class="brand-mark">FB</view><text>FLIPBELT 现场挑战</text></view><view v-if="completed > 0 || transitioning" class="history-trigger" :class="{ locked: !canGoBack }" aria-label="点击或下拉回退上一张卡片" @touchstart.stop="onHistoryTouchStart" @touchmove.stop="onHistoryTouchMove" @touchend.stop="onHistoryTouchEnd" @mousedown.stop="onHistoryMouseStart" @mousemove.stop="onHistoryMouseMove" @mouseup.stop="onHistoryMouseEnd"><view class="history-mini-stack" :class="{ pulling: historyPulling }" :style="historyStackStyle"><i v-for="item in Math.min(Math.max(completed, 1), 3)" :key="item" /></view></view></view>
    <view class="stack-title"><text class="stack-heading">40秒，装下你的本事！</text></view>
    <view v-if="loading" class="loading-card"><text>活动信息加载中…</text></view>
    <view v-else class="stack-deck" :class="{ dragging }" @touchstart="onTouchStart" @touchmove="onTouchMove" @touchend="onTouchEnd" @mousedown="onMouseStart" @mousemove="onMouseMove" @mouseup="onMouseEnd" @mouseleave="onMouseEnd">
      <view v-for="(step, layer) in visibleSteps" :key="`${current}-${layer}`" class="flow-card" :class="[toneFor(layer), layer === 0 ? 'front' : layer === 1 ? 'middle ghost-card' : 'back ghost-card', { 'leaving-forward': layer === 0 && leaving && transitionDirection === 'forward', 'leaving-backward': layer === 0 && leaving && transitionDirection === 'backward', returning: layer === 0 && returning }]" :style="cardStyle(layer)">
        <template v-if="layer > 0"><text class="ghost-number">{{ step.businessName }} · 下一张卡</text><text class="ghost-title">{{ step.title }}</text></template>
        <template v-else><view>
          <view v-if="step.content === 'video'" class="video-card-content"><view class="video-card-label"><text>{{ step.tag }}</text><text>卡片 {{ current + 1 }} / {{ steps.length }}</text></view><video class="demo-video demo-video--hero" :src="videoUrl" controls object-fit="contain" /><text class="video-card-caption">观看示范，准备上场</text></view>
          <template v-else><view class="card-topline"><text class="step-badge">{{ step.tag }}</text><text class="step-index">卡片 {{ current + 1 }} / {{ steps.length }}</text></view><text class="card-title">{{ step.title }}</text><text class="card-copy">{{ step.copy }}</text>
          <view v-if="step.content === 'follow'" class="qr-row"><view class="qr-tile"><image :src="xiaohongshuQrUrl" mode="aspectFit" /><text>小红书</text></view><view class="qr-tile"><image :src="douyinQrUrl" mode="aspectFit" /><text>抖音</text></view><view class="micro-list"><text>扫描现场二维码，完成关注后向工作人员出示</text><text>页面二维码可长按识别，测试版后续可替换</text></view></view>
          <view v-else-if="step.content === 'signup'" class="form-grid"><label>姓名<input v-model="form.name" placeholder="请输入姓名" maxlength="30" @touchstart.stop @touchmove.stop @touchend.stop @mousedown.stop @mousemove.stop @mouseup.stop /></label><label>手机号<input v-model="form.phone" type="number" placeholder="请输入11位手机号" maxlength="11" @touchstart.stop @touchmove.stop @touchend.stop @mousedown.stop @mousemove.stop @mouseup.stop /></label><label>参赛号码牌<input v-model="form.number_plate" placeholder="例如：A018" maxlength="30" @touchstart.stop @touchmove.stop @touchend.stop @mousedown.stop @mousemove.stop @mouseup.stop /></label><view class="micro-list"><text>号码牌由你自行保留；每人仅可挑战一次</text></view></view>
          <view v-else-if="step.content === 'rule-one'" class="single-media"><image class="rule-poster" :src="scorePosterUrl" mode="aspectFit" /></view>
          <view v-else-if="step.content === 'rule-two'" class="single-media"><image class="rule-poster" :src="rewardPosterUrl" mode="aspectFit" /></view>
          <view v-else-if="step.content === 'challenge'" class="status-box"><text class="status-title">● 当前状态：等待成绩登记</text><text>完成线下挑战后，向工作人员告知号码牌。工作人员登记完成，本页会显示成绩、排名与奖励。</text><view class="micro-list"><text>挑战结束后道具掉落不计分</text><text>请保留号码牌，方便工作人员查询</text></view></view>
          <view v-else class="result-content"><view class="result-score"><text>{{ me?.score ?? '--' }}</text><small>分</small></view><view class="rank-box"><text>当前全场排名</text><b>{{ me?.rank ? `第 ${me.rank} 名` : '成绩待更新' }}</b></view><view v-if="me?.reward" class="reward-box"><text>现场奖励</text><b>{{ me.reward.prize_name }}</b></view><view v-if="me?.draw_qualified" class="draw-tip">已达到 {{ activity?.draw_threshold }} 分进群抽奖门槛，请扫码进入微信群。</view><image v-if="me?.draw_qualified" class="group-qr" :src="groupQrUrl" mode="aspectFit" /></view></template>
        </view><view class="card-bottom"><button class="card-action" :loading="submitting" :disabled="transitioning" @tap.stop="advance">{{ actionText }}</button><text v-if="error" class="error">{{ error }}</text><text class="swipe-tip">{{ swipeTip }}</text></view></template>
      </view>
    </view>
    <view class="progress-dots"><i v-for="(_, index) in steps" :key="index" :class="{ active: index < completed || index === current }" /></view>
  </view></view>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import Taro from '@tarojs/taro'
import { api, hasToken, mediaUrl, saveToken, type Activity, type Me } from '../../services/api'

const steps = [
  { id: 'follow', business: 1, businessName: '第 1 步 · 关注确认', short: '关注确认', tag: '第 1 步 · 先完成关注', title: '关注品牌账号', copy: '扫描小红书和抖音二维码，完成关注后向工作人员出示。', content: 'follow', swipe: true },
  { id: 'signup', business: 2, businessName: '第 2 步 · 填写报名', short: '填写报名', tag: '第 2 步 · 领取号码牌', title: '填写参赛信息', copy: '填写姓名、手机号和工作人员发放的号码牌。', content: 'signup', swipe: false },
  { id: 'prepare-video', business: 3, businessName: '第 3 步 · 挑战准备', short: '示范视频', tag: '第 3 步 · 挑战准备 1/3', title: '先看挑战示范', copy: '观看视频，熟悉 40 秒能装挑战的节奏和动作。', content: 'video', swipe: true },
  { id: 'prepare-rule-one', business: 3, businessName: '第 3 步 · 挑战准备', short: '挑战规则', tag: '第 3 步 · 挑战准备 2/3', title: '挑战规则', copy: '上场前请单独查看这一张规则图。', content: 'rule-one', swipe: true },
  { id: 'prepare-rule-two', business: 3, businessName: '第 3 步 · 挑战准备', short: '计分与奖励', tag: '第 3 步 · 挑战准备 3/3', title: '计分与奖励', copy: '上场前请单独查看这一张计分与奖励图。', content: 'rule-two', swipe: true },
  { id: 'challenge', business: 4, businessName: '第 4 步 · 现场挑战', short: '现场挑战', tag: '第 4 步 · 线下现场完成', title: '告诉工作人员你的号码牌', copy: '线下完成挑战后，工作人员会录入有效道具数量。', content: 'challenge', swipe: false },
  { id: 'result', business: 5, businessName: '第 5 步 · 查看成绩', short: '查看成绩', tag: '第 5 步 · 成绩与排名', title: '你的挑战成绩', copy: '成绩、排名与奖励均以现场工作人员登记为准。', content: 'result', swipe: false }
] as const
const tones = ['tone-slate', 'tone-purple', 'tone-teal', 'tone-pink', 'tone-yellow']
const activity = ref<Activity>(); const me = ref<Me>(); const loading = ref(true); const submitting = ref(false); const error = ref(''); const current = ref(0); const completed = ref(0); const dragging = ref(false); const transitioning = ref(false); const leaving = ref(false); const returning = ref(false); const transitionDirection = ref<'forward' | 'backward'>('forward'); const startX = ref(0); const startY = ref(0); const dragX = ref(0); const dragY = ref(0); const historyStartY = ref(0); const historyDragY = ref(0); const historyPulling = ref(false)
const form = reactive({ name: '', phone: '', number_plate: '' })
const visibleSteps = computed(() => steps.slice(current.value, current.value + 3))
const canGoBack = computed(() => current.value >= 2)
const historyStackStyle = computed(() => { const pull = Math.min(1, Math.max(0, historyDragY.value / 90)); return historyPulling.value ? { transform: `translate3d(0, ${pull * 12}px, 0) scale(${1 - pull * .06}) rotateX(${-pull * 12}deg)` } : {} })
function activityMediaUrl(kinds: string[], fallback: string) { const asset = activity.value?.media_assets.find((item) => kinds.includes(item.kind)); return mediaUrl(asset?.url || fallback) }
const xiaohongshuQrUrl = computed(() => activityMediaUrl(['xiaohongshu_qr'], '/assets/小红书二维码测试版.png'))
const douyinQrUrl = computed(() => activityMediaUrl(['douyin_qr'], '/assets/抖音二维码测试版.png'))
const videoUrl = computed(() => activityMediaUrl(['video', 'demo_video'], '/assets/袋鼠裤.mp4'))
const scorePosterUrl = computed(() => activityMediaUrl(['score_rule', 'rule_one'], '/assets/image.png'))
const rewardPosterUrl = computed(() => activityMediaUrl(['reward_rule', 'rule_two'], '/assets/image2.png'))
const groupQrUrl = computed(() => activityMediaUrl(['group_qr'], '/assets/测试群二维码.jpg'))
const actionText = computed(() => ['已向工作人员出示，继续报名', '提交报名，查看挑战准备', '视频看完了，查看挑战规则', '已了解，查看计分与奖励', '准备好了，去现场挑战', '刷新我的成绩', '刷新成绩与排名'][current.value])
const swipeTip = computed(() => canGoBack.value ? '上滑卡片继续 · 点击或下拉右上角卡堆回退' : steps[current.value]?.swipe ? '上滑卡片继续' : '点击继续')
function toneFor(layer: number) { return tones[(current.value + layer) % tones.length] }
function beginHistoryPull(clientY: number) { if (!canGoBack.value || transitioning.value) return; historyStartY.value = clientY; historyDragY.value = 0; historyPulling.value = true }
function moveHistoryPull(clientY: number) { if (historyPulling.value) historyDragY.value = Math.max(0, clientY - historyStartY.value) }
function endHistoryPull(clientY: number) { if (!historyPulling.value) return; const pull = Math.max(0, clientY - historyStartY.value); historyPulling.value = false; historyDragY.value = 0; if (pull > 52 || pull < 10) void rewindOne() }
function onHistoryTouchStart(event: TouchEvent) { const touch = event.touches[0]; if (touch) beginHistoryPull(touch.clientY) }
function onHistoryTouchMove(event: TouchEvent) { const touch = event.touches[0]; if (touch) moveHistoryPull(touch.clientY) }
function onHistoryTouchEnd(event: TouchEvent) { const touch = event.changedTouches[0]; if (touch) endHistoryPull(touch.clientY) }
function onHistoryMouseStart(event: MouseEvent) { if (event.button === 0) beginHistoryPull(event.clientY) }
function onHistoryMouseMove(event: MouseEvent) { moveHistoryPull(event.clientY) }
function onHistoryMouseEnd(event: MouseEvent) { endHistoryPull(event.clientY) }
function onShellMouseMove(event: MouseEvent) { moveHistoryPull(event.clientY) }
function onShellMouseEnd(event: MouseEvent) { endHistoryPull(event.clientY) }
function cardStyle(layer: number) { if (layer > 0 || !dragging.value) return {}; const progress = Math.min(1, Math.max(0, Math.abs(dragY.value) / 210)); const direction = dragY.value < 0 ? 1 : -1; return { transform: `translate3d(${dragX.value}px, ${Math.max(-240, Math.min(120, dragY.value))}px, 45px) scale(${1 - progress * .18}) rotate(${dragX.value * .04 + direction * progress * 5}deg)`, opacity: String(1 - progress * .12), transition: 'none' } }
function beginDrag(clientX: number, clientY: number) { if (transitioning.value) return; startX.value = clientX; startY.value = clientY; dragX.value = 0; dragY.value = 0; dragging.value = true }
function moveDrag(clientX: number, clientY: number) { if (!dragging.value) return; dragX.value = clientX - startX.value; dragY.value = clientY - startY.value }
function endDrag() { if (!dragging.value) return; const advanceCard = -dragY.value > 92 || (-dragY.value > 48 && Math.abs(dragX.value) > 46); const rewindCard = dragY.value > 92 || (dragY.value > 48 && Math.abs(dragX.value) > 46); dragging.value = false; if (advanceCard) void advance(); else if (rewindCard) void rewindOne() }
function onTouchStart(event: TouchEvent) { const touch = event.touches[0]; if (touch) beginDrag(touch.clientX, touch.clientY) }
function onTouchMove(event: TouchEvent) { const touch = event.touches[0]; if (touch) moveDrag(touch.clientX, touch.clientY) }
function onTouchEnd() { endDrag() }
function onMouseStart(event: MouseEvent) { if (event.button === 0) beginDrag(event.clientX, event.clientY) }
function onMouseMove(event: MouseEvent) { moveDrag(event.clientX, event.clientY) }
function onMouseEnd() { endDrag() }
async function advance() { error.value = ''; if (transitioning.value) return; if (current.value === 1) return register(); if (current.value === 5 || current.value === 6) return refreshScore(); finishStep() }
function finishStep() { if (transitioning.value || current.value >= steps.length - 1) return; transitionDirection.value = 'forward'; transitioning.value = true; leaving.value = true; setTimeout(() => { completed.value = Math.max(completed.value, current.value + 1); current.value += 1; leaving.value = false; transitioning.value = false }, 430) }
async function rewindOne() { if (!canGoBack.value || transitioning.value) return; transitionDirection.value = 'backward'; transitioning.value = true; current.value -= 1; returning.value = true; await new Promise<void>((resolve) => setTimeout(resolve, 430)); returning.value = false; transitioning.value = false; error.value = '' }
async function resumeExistingRegistration(channel: string, externalId: string) { const result = await api.login({ channel, external_id: externalId }); saveToken(result.access_token); await loadProfile(); if (!me.value?.registered) throw new Error('未找到该报名信息'); completed.value = me.value.score == null ? 5 : 6; current.value = me.value.score == null ? 5 : 6; Taro.showToast({ title: '已进入你的报名进度', icon: 'success' }) }
async function register() { if (!activity.value || !form.name.trim() || !/^1\d{10}$/.test(form.phone) || !form.number_plate.trim()) { error.value = '请正确填写姓名、11位手机号和号码牌。'; return }; submitting.value = true; const isWeapp = Taro.getEnv() === Taro.ENV_TYPE.WEAPP; const channel = isWeapp ? 'wechat' : 'h5'; const externalId = isWeapp ? `wx-dev-${form.phone}` : form.phone; try { const result = await api.register({ activity_slug: activity.value.slug, channel, external_id: externalId, ...form }); saveToken(result.access_token); await loadProfile(); Taro.showToast({ title: '报名成功', icon: 'success' }); finishStep() } catch (err) { const message = err instanceof Error ? err.message : '报名失败，请联系工作人员'; if (message.includes('已报名')) { try { await resumeExistingRegistration(channel, externalId); return } catch { error.value = '该手机号或号码牌已被使用，请核对信息后重试。'; return } }; error.value = message } finally { submitting.value = false } }
async function refreshScore() { if (!hasToken()) { error.value = '请先完成报名。'; return }; submitting.value = true; try { await loadProfile(); if (me.value?.score != null && current.value === 5) finishStep(); else Taro.showToast({ title: me.value?.score == null ? '成绩暂未登记，请稍后刷新' : '成绩已更新', icon: 'none' }) } catch { error.value = '成绩加载失败，请联系工作人员。' } finally { submitting.value = false } }
async function loadProfile() { if (hasToken()) me.value = await api.me() }
onMounted(async () => { try { activity.value = await api.currentActivity() } catch { error.value = '活动信息加载失败，请刷新后重试。' } finally { loading.value = false } })
</script>

<style lang="scss">
.stack-page{min-height:100vh;padding:28rpx;background:linear-gradient(135deg,#0f172a,#1e293b)}.stack-shell{width:100%;max-width:1075rpx;min-height:calc(100vh - 56rpx);margin:0 auto;overflow:hidden;border:1rpx solid rgba(255,255,255,.16);border-radius:44rpx;background:#1a1a2e;box-shadow:0 24rpx 55rpx rgba(0,0,0,.34)}.stack-header{display:flex;align-items:center;justify-content:space-between;padding:30rpx 32rpx 22rpx;color:#fff;font-size:30rpx;font-weight:700}.brand,.history-trigger{display:flex;align-items:center;gap:14rpx}.brand-mark{display:grid;width:54rpx;height:54rpx;place-items:center;border-radius:16rpx;background:#6c5ce7;font-size:25rpx}.history-trigger{width:70rpx;height:58rpx;justify-content:flex-end}.history-trigger.locked{opacity:.45}.history-mini-stack{position:relative;width:52rpx;height:42rpx;transition:transform .2s ease}.history-trigger:active:not(.locked) .history-mini-stack{transform:translateY(8rpx) scale(.94)}.history-mini-stack i{position:absolute;display:block;width:36rpx;height:28rpx;border:1rpx solid rgba(255,255,255,.35);border-radius:10rpx;box-shadow:0 6rpx 12rpx rgba(0,0,0,.25)}.history-mini-stack i:nth-child(1){left:2rpx;top:10rpx;background:#fd79a8;transform:rotate(-7deg)}.history-mini-stack i:nth-child(2){left:9rpx;top:5rpx;background:#00cec9;transform:rotate(4deg)}.history-mini-stack i:nth-child(3){left:16rpx;top:0;background:#ffeaa7;transform:rotate(-1deg)}.stack-title{display:flex;flex-direction:column;padding:0 32rpx;color:#c8c4d5;font-size:30rpx}.stack-heading{margin-top:10rpx;color:#fff;font-size:65rpx;line-height:1.2;font-weight:700;letter-spacing:-2rpx}.loading-card{margin:32rpx;padding:60rpx 30rpx;border-radius:36rpx;background:#f0f0f5;text-align:center}
.stack-deck{position:relative;height:1420rpx;margin:30rpx 32rpx 0;perspective:1100rpx;transform-style:preserve-3d;touch-action:none}.flow-card{position:absolute;display:flex;flex-direction:column;justify-content:space-between;overflow:hidden;padding:32rpx;border:1rpx solid rgba(24,24,27,.13);border-radius:36rpx;color:var(--card-ink);background:var(--card-color);box-shadow:0 26rpx 45rpx rgba(0,0,0,.28),0 8rpx 18rpx rgba(0,0,0,.12);transform-style:preserve-3d;transform-origin:center bottom;transition:transform .43s cubic-bezier(.2,.8,.2,1),opacity .43s ease-out,box-shadow .43s ease-out;user-select:none;cursor:grab}.dragging .front{cursor:grabbing}.tone-slate{--card-color:#f0f0f5;--card-ink:#1a1a2e;--card-muted:#52525b;--card-surface:rgba(255,255,255,.78);--card-line:rgba(24,24,27,.14)}.tone-purple{--card-color:#6c5ce7;--card-ink:#fff;--card-muted:#f0efff;--card-surface:rgba(255,255,255,.18);--card-line:rgba(255,255,255,.3)}.tone-teal{--card-color:#00cec9;--card-ink:#102a31;--card-muted:#164a51;--card-surface:rgba(255,255,255,.35);--card-line:rgba(16,42,49,.18)}.tone-pink{--card-color:#fd79a8;--card-ink:#351424;--card-muted:#5f1f39;--card-surface:rgba(255,255,255,.36);--card-line:rgba(53,20,36,.16)}.tone-yellow{--card-color:#ffeaa7;--card-ink:#342d19;--card-muted:#5d5028;--card-surface:rgba(255,255,255,.48);--card-line:rgba(52,45,25,.15)}.front{z-index:30;inset:0 0 210rpx;transform:translate3d(0,0,42rpx) scale(1)}.front>view:first-child{display:flex;min-height:0;flex:1;flex-direction:column}.middle{z-index:20;inset:auto 12rpx 62rpx;height:310rpx;transform:translate3d(0,0,0) scale(.95) rotate(2deg);opacity:.8}.back{z-index:10;inset:auto 24rpx 0;height:300rpx;transform:translate3d(0,0,-42rpx) scale(.9) rotate(-3deg);opacity:.6}.dragging .middle{transform:translate3d(-27rpx,28rpx,0) scale(.95) rotate(6deg);opacity:.9}.dragging .back{transform:translate3d(28rpx,43rpx,-42rpx) scale(.9) rotate(-6deg);opacity:.75}.front.leaving-forward,.front.leaving-backward{transform:transl